module serial2parallel(
    input clk, input rst_n, input din_serial, input din_valid,
    output reg [7:0] dout_parallel, output reg dout_valid
);
    reg [3:0] cnt;
    reg [7:0] din_tmp;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 4'd0;
        else if (cnt == 4'd8)
            cnt <= 4'd0;
        else
            cnt <= cnt + 1;
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            din_tmp <= 8'd0;
        else if (din_valid && cnt <= 4'd7)
            din_tmp <= {din_tmp[6:0], din_serial};
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            dout_valid <= 1'b0;
        else if (cnt == 4'd8)
            dout_valid <= 1'b1;
        else
            dout_valid <= 1'b0;
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            dout_parallel <= 8'd0;
        else if (cnt == 4'd8)
            dout_parallel <= din_tmp;
    end
endmodule

module div_8bit(
    input clk, input rst, input sign, input [7:0] dividend, input [7:0] divisor, input opn_valid, input res_ready,
    output res_valid, output [15:0] result
);
    // Divisor extension logic
    wire [8:0] divisor_extend = (sign && divisor[7]) ? {1'b1, divisor} : {1'b0, divisor};

    // Negative divisor register
    reg [8:0] NEG_DIVISOR;
    always @(posedge clk or negedge rst) begin
        if (!rst)
            NEG_DIVISOR <= 9'b0;
        else if (sign && divisor[7])
            NEG_DIVISOR <= {1'b1, divisor};
        else
            NEG_DIVISOR <= {1'b0, divisor};
    end

    // Subtraction result register
    reg [9:0] all_sub_result;
    wire [8:0] sub_result = all_sub_result[8:0];

    // Remainder and quotient registers
    reg [15:0] SR;
    wire [7:0] REMAINER = SR[15:8];
    wire [7:0] QUOTIENT = SR[7:0];
    wire CO = all_sub_result[9];

    // Multiplication result
    wire [8:0] mux_result = CO ? sub_result : REMAINER;

    // Quotient shift register
    reg [6:0] quotient_shift;
    always @(posedge clk or negedge rst) begin
        if (!rst)
            quotient_shift <= 7'b0;
        else
            quotient_shift <= {mux_result[6:0], quotient_shift[5:0], CO};
    end

    // Final remainder and quotient logic
    wire [7:0] final_remainer = (sign && dividend[7]) ? (~REMAINER + 1) : REMAINER;
    wire [7:0] final_quotient = (sign && dividend[7]) ? (~QUOTIENT + 1) : QUOTIENT;

    // Result validity logic
    reg res_valid;
    always @(*) begin
        if (rst)
            res_valid = 1'b0;
        else if (opn_valid && !res_ready)
            res_valid = 1'b1;
        else if (res_valid && res_ready)
            res_valid = 1'b0;
        else
            res_valid = res_valid;
    end

    // Result output
    assign result = {final_remainer, final_quotient};

    // Division process control
    reg [3:0] cnt;
    wire [3:0] next_cnt = cnt + 1;
    always @(posedge clk or negedge rst) begin
        if (!rst)
            cnt <= 4'b0;
        else if (opn_valid && !res_ready)
            cnt <= 4'b1;
        else if (cnt == 4'b1000)
            cnt <= 4'b0;
        else
            cnt <= next_cnt;
    end

    // Subtraction result calculation
    always @(posedge clk or negedge rst) begin
        if (!rst)
            all_sub_result <= 10'b0;
        else
            all_sub_result <= {REMAINER, 1'b0} + NEG_DIVISOR;
    end

    // Shift register update
    always @(posedge clk or negedge rst) begin
        if (!rst)
            SR <= 16'b0;
        else
            SR <= {mux_result, quotient_shift, CO, 1'b0};
    end

    // Absolute value of dividend
    wire [7:0] dividend_abs = (sign && dividend[7]) ? (~dividend + 1) : dividend;

    // Final quotient sign
    wire is_final_quotient_sign = sign & (dividend[7] ^ divisor[7]);
endmodule

module width_8to16(
    input clk, input rst_n, input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);
    parameter WIDTH_IN = 8;
    parameter WIDTH_OUT = 16;
    reg [WIDTH_IN-1:0] data_lock;
    reg flag;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 16'd0;
            valid_out <= 1'b0;
        end else if (valid_in && flag) begin
            data_out <= {data_lock, data_in};
            valid_out <= 1'b1;
        end else begin
            valid_out <= 1'b0;
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_lock <= 8'd0;
        end else if (valid_in && !flag) begin
            data_lock <= data_in;
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            flag <= 1'b0;
        end else if (valid_in && !flag) begin
            flag <= 1'b1;
        end else if (valid_in && flag) begin
            flag <= 1'b0;
        end
    end
endmodule

module pe(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output [31:0] c
);
    reg [31:0] acc_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            acc_reg <= 32'b0;
        end else begin
            acc_reg <= acc_reg + (a * b);
        end
    end

    assign c = acc_reg;

endmodule

module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 0;
parameter s1_red = 1;
parameter s2_yellow = 2;
parameter s3_green = 3;

reg [1:0] state;
reg [5:0] cnt;
reg p_red, p_yellow, p_green;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        cnt <= 10;
    end
    else begin
        case (state)
            idle: begin
                state <= s1_red;
            end
            s1_red: begin
                if (cnt == 3) begin
                    state <= s3_green;
                    cnt <= 60;
                end
                else begin
                    state <= s1_red;
                    cnt <= cnt - 1;
                end
            end
            s2_yellow: begin
                if (cnt == 3) begin
                    state <= s1_red;
                    cnt <= 10;
                end
                else begin
                    state <= s2_yellow;
                    cnt <= cnt - 1;
                end
            end
            s3_green: begin
                if (cnt == 3) begin
                    state <= s2_yellow;
                    cnt <= 5;
                end
                else begin
                    state <= s3_green;
                    cnt <= cnt - 1;
                end
            end
            default: begin
                state <= idle;
            end
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end
    else begin
        case (state)
            s1_red: begin
                p_red <= 1;
                p_yellow <= 0;
                p_green <= 0;
            end
            s2_yellow: begin
                p_red <= 0;
                p_yellow <= 1;
                p_green <= 0;
            end
            s3_green: begin
                p_red <= 0;
                p_yellow <= 0;
                p_green <= 1;
            end
            default: begin
                p_red <= 0;
                p_yellow <= 0;
                p_green <= 0;
            end
        endcase
    end
end

assign clock = cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        red <= 0;
        yellow <= 0;
        green <= 0;
    end
    else begin
        red <= p_red;
        yellow <= p_yellow;
        green <= p_green;
    end
end

endmodule

