module multi_pipe_8bit(
    input clk,
    input rst_n,
    input mul_en_in,
    input [7:0] mul_a,
    input [7:0] mul_b,
    output mul_en_out,
    output [15:0] mul_out
);

    reg [2:0] mul_en_out_reg;
    reg [7:0] mul_a_reg;
    reg [7:0] mul_b_reg;
    wire [15:0] temp [7:0];
    reg [15:0] sum [7:0];
    reg [15:0] mul_out_reg;

    assign mul_en_out = mul_en_out_reg[2];
    assign mul_out = mul_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_en_out_reg <= 3'b0;
        end else begin
            mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_a_reg <= 8'b0;
            mul_b_reg <= 8'b0;
        end else if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
        end
    end

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin
            assign temp[i] = mul_b_reg[i] ? {8'b0, mul_a_reg} << i : 16'b0;
        end
    endgenerate

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int i = 0; i < 8; i = i + 1) begin
                sum[i] <= 16'b0;
            end
        end else begin
            sum[0] <= temp[0];
            for (int i = 1; i < 8; i = i + 1) begin
                sum[i] <= sum[i-1] + temp[i];
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_out_reg <= 16'b0;
        end else begin
            mul_out_reg <= sum[7];
        end
    end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [3:0] data;
    reg [1:0] cnt;
    reg valid;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0;
            valid <= 0;
        end
        else begin
            if (cnt == 2'd3) begin
                data <= d;
                cnt <= 0;
                valid <= 1;
            end
            else begin
                cnt <= cnt + 1;
                valid <= 0;
                data <= {data[2:0], data[3]};
            end
        end
    end

    assign dout = data[3];
    assign valid_out = valid;

endmodule

module div_16bit(
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg, b_reg;
    reg [15:0] quotient, remainder;
    integer i;

    always @(A, B) begin
        a_reg <= A;
        b_reg <= B;
    end

    always @(a_reg, b_reg) begin
        quotient <= 0;
        remainder <= 0;

        for (i = 15; i >= 0; i = i - 1) begin
            remainder <= {remainder[14:0], a_reg[i]};
            if (remainder >= b_reg) begin
                remainder <= remainder - b_reg;
                quotient[i] <= 1'b1;
            end
        end
    end

    assign result = quotient;
    assign odd = remainder;

endmodule

module multi_8bit(
    input [7:0] A,
    input [7:0] B,
    output [15:0] product
);

    reg [15:0] product_reg;
    integer i;

    always @(*) begin
        product_reg = 16'b0;
        for (i = 0; i < 8; i = i + 1) begin
            if (B[i] == 1'b1) begin
                product_reg = product_reg + (A << i);
            end
        end
    end

    assign product = product_reg;

endmodule

module fsm(
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);

    // Define the states
    parameter s0 = 3'b000, s1 = 3'b001, s2 = 3'b010, s3 = 3'b011, s4 = 3'b100, s5 = 3'b101;

    // Current state register
    reg [2:0] ST_cr;

    // Next state logic
    reg [2:0] ST_nt;
    always @(*) begin
        case (ST_cr)
            s0: begin
                if (IN == 1'b0)
                    ST_nt = s1;
                else
                    ST_nt = s0;
            end
            s1: begin
                if (IN == 1'b0)
                    ST_nt = s2;
                else
                    ST_nt = s0;
            end
            s2: begin
                if (IN == 1'b0)
                    ST_nt = s3;
                else
                    ST_nt = s0;
            end
            s3: begin
                if (IN == 1'b0)
                    ST_nt = s0;
                else
                    ST_nt = s4;
            end
            s4: begin
                if (IN == 1'b0)
                    ST_nt = s2;
                else
                    ST_nt = s5;
            end
            s5: begin
                if (IN == 1'b0)
                    ST_nt = s2;
                else
                    ST_nt = s1;
            end
            default: begin
                ST_nt = s0;
            end
        endcase
    end

    // State register update
    always @(posedge CLK or posedge RST) begin
        if (RST)
            ST_cr <= s0;
        else
            ST_cr <= ST_nt;
    end

    // Output logic
    always @(*) begin
        if (RST)
            MATCH = 1'b0;
        else if (ST_cr == s4 && IN == 1'b1)
            MATCH = 1'b1;
        else
            MATCH = 1'b0;
    end

endmodule

