module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [32:0] res;
    wire signed [31:0] a_signed, b_signed;
    assign a_signed = a;
    assign b_signed = b;

    assign r = res[31:0];
    assign zero = res[31:0] == 32'b0;
    assign carry = (aluc == ADD || aluc == ADDU || aluc == SUB || aluc == SUBU) ? res[32] : 1'b0;
    assign negative = res[31];
    assign overflow = (aluc == ADD) ? ((~a_signed[31] & ~b_signed[31] & res[31]) | (a_signed[31] & b_signed[31] & ~res[31])) : 
                       (aluc == SUB) ? ((a_signed[31] & ~b_signed[31] & ~res[31]) | (~a_signed[31] & b_signed[31] & res[31])) :
                       1'b0;
    assign flag = (aluc == SLT) ? res[31] : (aluc == SLTU) ? ~res[31] : 1'b0;

    always @(*) begin
        case (aluc)
            ADD: res = {a_signed[31], a_signed} + {b_signed[31], b_signed};
            ADDU: res = {1'b0, a} + {1'b0, b};
            SUB: res = {a_signed[31], a_signed} - {b_signed[31], b_signed};
            SUBU: res = {1'b0, a} - {1'b0, b};
            AND: res = {1'b0, a & b};
            OR: res = {1'b0, a | b};
            XOR: res = {1'b0, a ^ b};
            NOR: res = {1'b0, ~(a | b)};
            SLT: res = {1'b0, a_signed < b_signed};
            SLTU: res = {1'b0, a < b};
            SLL: res = {a[31:0], a[31:0] << b[4:0]};
            SRL: res = {a[31:0], a[31:0] >> b[4:0]};
            SRA: res = {a[31:0], a[31:0] >>> b[4:0]};
            SLLV: res = {a[31:0], a[31:0] << b[4:0]};
            SRLV: res = {a[31:0], a[31:0] >> b[4:0]};
            SRAV: res = {a[31:0], a[31:0] >>> b[4:0]};
            LUI: res = {b[15:0], 16'b0};
            default: res = 33'b0;
        endcase
    end

endmodule

module edge_detect(
    input clk, input rst_n, input a,
    output reg rise, output reg down
);
    reg a_delay;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_delay <= 0;
            rise <= 0;
            down <= 0;
        end else begin
            a_delay <= a;
            if (a && !a_delay) begin
                rise <= 1;
                down <= 0;
            end else if (!a && a_delay) begin
                rise <= 0;
                down <= 1;
            end else begin
                rise <= 0;
                down <= 0;
            end
        end
    end
endmodule

module adder_16bit(
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output [15:0] y,
    output Co
);
wire [15:0] sum;
wire [15:0] carry;

// 8-bit adder instantiation
wire [7:0] sum_low;
wire [7:0] sum_high;
wire carry_low;
wire carry_high;

// Low bits
assign {carry_low, sum_low} = a[7:0] + b[7:0] + Cin;

// High bits
assign {carry_high, sum_high} = a[15:8] + b[15:8] + carry_low;

// Output assignment
assign sum = {sum_high, sum_low};
assign carry = {carry_high, carry_low};

assign y = sum;
assign Co = carry[15];

endmodule

module multi_pipe_4bit(
    input clk, input rst_n,
    input [3:0] mul_a, mul_b,
    output [7:0] mul_out
);
    parameter size = 4;
    reg [2*size-1:0] partial_products [size-1:0];
    reg [2*size-1:0] registers [size/2-1:0];
    reg [2*size-1:0] product;
    // Multiplication operation
    integer i;
    always @(*) begin
        for (i = 0; i < size; i = i + 1) begin
            if (mul_b[i]) begin
                partial_products[i] = mul_a << i;
            end else begin
                partial_products[i] = 0;
            end
        end
    end
    // Add of partial products
    always @(*) begin
        for (i = 0; i < size/2; i = i + 1) begin
            registers[i] = partial_products[2*i] + partial_products[2*i+1];
        end
    end
    // Final product calculation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            product <= 0;
        end else begin
            product <= registers[0] + registers[1];
        end
    end
    assign mul_out = product;
endmodule

module calendar (
    input wire CLK,
    input wire RST,
    output reg [5:0] Hours,
    output reg [5:0] Mins,
    output reg [5:0] Secs
);

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Secs <= 6'b000000;
        Mins <= 6'b000000;
        Hours <= 6'b000000;
    end
    else begin
        if (Secs == 6'd59) begin
            Secs <= 6'b000000;
            if (Mins == 6'd59) begin
                Mins <= 6'b000000;
                if (Hours == 6'd23) begin
                    Hours <= 6'b000000;
                end
                else begin
                    Hours <= Hours + 1;
                end
            end
            else begin
                Mins <= Mins + 1;
            end
        end
        else begin
            Secs <= Secs + 1;
        end
    end
end

endmodule

