module pulse_detect(
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    parameter s0 = 2'b00;
    parameter s1 = 2'b01;
    parameter s2 = 2'b10;
    parameter s3 = 2'b11;

    reg [1:0] pulse_level1;
    reg [1:0] pulse_level2;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            pulse_level1 <= s0;
        end else begin
            pulse_level1 <= pulse_level2;
        end
    end

    always @(*) begin
        if (pulse_level1 == s0) begin
            if (data_in == 1'b0) begin
                pulse_level2 = s1;
            end else begin
                pulse_level2 = s0;
            end
        end else if (pulse_level1 == s1) begin
            if (data_in == 1'b1) begin
                pulse_level2 = s2;
            end else begin
                pulse_level2 = s1;
            end
        end else if (pulse_level1 == s2) begin
            if (data_in == 1'b0) begin
                pulse_level2 = s3;
